/*
 * A287312  Primes that can be generated by the concatenation in base 9, in
 *          ascending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287312
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 26, u32 n <= 26, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A287312 – primes obtained by concatenating the base‑9 representations
   of two consecutive decimal integers (i and i+1).
   For each i>=1 let len be the number of base‑9 digits of i+1.
   The candidate number is  i * 9^len + (i+1).  If it is prime it
   enters the sequence.  The function caches results so that calls
   with arbitrary n are answerable in O(n) cumulative time.  */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"      /* provides bool is_prime_big(seq_t) */

static seq_t *cache      = NULL;   /* cached sequence values   */
static size_t  cache_cap = 0;      /* current capacity         */
static size_t  cache_cnt = 0;      /* number of values stored  */
static idx_t   next_i     = 1;     /* next i to examine       */

seq_t a(idx_t n)
{
    /* handle offset: a(1) is the first term */
    if (n == 0) return 0;          /* undefined, but harmless */

    /* extend cache until it contains at least n elements */
    while (cache_cnt < n) {
        idx_t i   = next_i++;
        idx_t next = i + 1;

        /* compute the number of base‑9 digits of (i+1) */
        size_t len = 0;
        idx_t  t   = next;
        do {
            ++len;
            t /= 9;
        } while (t > 0);

        /* pow9 = 9^len  (computed in seq_t space) */
        seq_t pow9 = 1;
        for (size_t k = 0; k < len; ++k)
            pow9 *= (seq_t)9;

        /* candidate number in decimal */
        seq_t val = (seq_t)i * pow9 + (seq_t)next;

        /* test primality */
        if (is_prime_big(val)) {
            /* grow cache if necessary */
            if (cache_cnt + 1 > cache_cap) {
                cache_cap = (cache_cap == 0) ? 8 : cache_cap * 2;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[cache_cnt++] = val;
        }
    }

    return cache[n - 1];
}
